mapper.select:
select id, plan_id, chapter_no, index_name, chapter_outline, status, index_id, word_count, summary,
create_time, update_time
from ai_chapter_plan
where plan_id = #{planId}

    and status = #{status}

order by chapter_no asc

select t1.*, t2.pen_name, t3.book_name
from ai_creation_task t1
left join author t2 on t1.author_id = t2.id
left join ai_creation_plan p on t1.plan_id = p.id
left join book t3 on p.book_id = t3.id


        and t1.plan_id = #{planId}


        and t1.status = #{status}


        and t1.task_type = #{taskType}


order by t1.id desc

select id, plan_id, author_id, task_type, chapter_no, status, running_flag, error_msg, create_time, update_time
from ai_creation_task
where id = #{id}
